'use strict';
(()=>{
 const palettes=['#ba8bff','#5de1cb','#ffb66d','#f477bc','#7eaeff','#e9de87','#ec8f91','#81d8a9'];
 const material=(c,metalness=0,roughness=.65)=>new THREE.MeshStandardMaterial({color:c,metalness,roughness});
 function mesh(g,m,parent,x=0,y=0,z=0){const o=new THREE.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
 function sphere(parent,m,x,y,z,sx,sy=sx,sz=sx){const o=mesh(new THREE.SphereGeometry(1,20,14),m,parent,x,y,z);o.scale.set(sx,sy,sz);return o}
 function box(parent,m,x,y,z,w,h,d,r=0){const o=mesh(new THREE.BoxGeometry(w,h,d),m,parent,x,y,z);o.rotation.z=r;return o}
 function capsule(parent,m,length,radius,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);mesh(new THREE.CylinderGeometry(radius,radius,length,16),m,g);sphere(g,m,0,length/2,0,radius);sphere(g,m,0,-length/2,0,radius);return g}
 function defaultFace(index){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d'),skin=['#e7b78e','#bb805d','#f0c6a0','#965e48'][index%4];x.fillStyle=skin;x.fillRect(0,0,256,256);x.fillStyle='#282137';x.beginPath();x.ellipse(83,105,10,14,0,0,7);x.ellipse(173,105,10,14,0,0,7);x.fill();x.strokeStyle='#44303b';x.lineWidth=7;x.lineCap='round';x.beginPath();x.arc(128,142,39,.15,Math.PI-.15);x.stroke();x.fillStyle='#f4d2b1';x.beginPath();x.ellipse(128,128,12,18,0,0,7);x.fill();x.strokeStyle='#3e2833';x.lineWidth=6;x.beginPath();x.moveTo(68,75);x.lineTo(95,71);x.moveTo(161,71);x.lineTo(188,75);x.stroke();const texture=new THREE.CanvasTexture(c);texture.encoding=THREE.sRGBEncoding;return texture}
 function createCharacter(type,index=0){const root=new THREE.Group(),body=new THREE.Group();root.add(body);const color=palettes[index%palettes.length],fabric=material(type==='disco'?'#d4c7ee':type==='astronaut'?'#e9e8ef':color,type==='disco'?.65:.05,type==='disco'?.28:.72),pants=material(type==='sport'?color:type==='astronaut'?'#c3c7d7':'#20233b',.05,.75),black=material('#141524'),white=material('#f3f0fa',.1,.48),skin=material('#d8a780'),trim=material(color,.45,.3);const hip=new THREE.Group();hip.position.y=1.28;body.add(hip);sphere(body,fabric,0,2.02,0,.52,.7,.3);sphere(body,pants,0,1.4,0,.4,.22,.27);const chest=box(body,type==='disco'?black:white,0,2.09,.285,.2,.65,.035);if(type==='street'){sphere(body,fabric,0,2.47,-.1,.45,.25,.32);for(const sign of [-1,1])capsule(body,white,.28,.018,sign*.13,2.26,.31)}if(type==='astronaut'){box(body,black,0,2.09,.3,.42,.4,.06);for(let i=0;i<3;i++)sphere(body,material(['#73ead9','#b19aff','#ff9aab'][i]),-.12+i*.12,2.1,.35,.035);box(body,pants,0,2.04,-.4,.7,.7,.28)}if(type==='disco'){for(const sign of [-1,1])box(body,trim,sign*.23,2.2,.28,.13,.5,.03,sign*.3);box(body,trim,0,1.5,.27,.6,.08,.07)}if(type==='sport'){for(const sign of [-1,1])box(body,white,sign*.38,2.05,.18,.06,.7,.08)}
 const neck=mesh(new THREE.CylinderGeometry(.12,.14,.23,16),skin,body,0,2.67,0),head=new THREE.Group();head.position.y=2.99;body.add(head);sphere(head,skin,0,0,0,.44,.47,.38);for(const sign of [-1,1])sphere(head,skin,sign*.44,-.02,0,.07,.12,.06);sphere(head,black,0,.29,-.03,.44,.24,.36);if(type==='street'){const cap=sphere(head,trim,0,.31,0,.46,.24,.4);box(head,trim,0,.28,.34,.66,.045,.32)}if(type==='disco'){for(let i=0;i<7;i++){const spike=mesh(new THREE.ConeGeometry(.12,.42,6),trim,head,(i-3)*.1,.49-Math.abs(i-3)*.035,0);spike.rotation.z=-(i-3)*.13}}if(type==='sport'){const band=mesh(new THREE.TorusGeometry(.43,.045,8,32),white,head,0,.18,0);band.rotation.x=Math.PI/2}if(type==='astronaut'){const halo=mesh(new THREE.TorusGeometry(.49,.065,10,40),white,head,0,0,.16);sphere(head,white,0,.09,-.1,.49,.52,.35)}
 const face=mesh(new THREE.CircleGeometry(.4,40),new THREE.MeshBasicMaterial({map:defaultFace(index)}),head,0,0,.369),faceAnchor=new THREE.Object3D();faceAnchor.position.set(0,0,.4);head.add(faceAnchor);
 const limbs={};for(const [key,sign]of [['L',-1],['R',1]]){const arm=new THREE.Group();arm.position.set(sign*.5,2.38,0);body.add(arm);capsule(arm,fabric,.5,.155,0,-.24,0);const elbow=new THREE.Group();elbow.position.y=-.56;arm.add(elbow);capsule(elbow,type==='sport'||type==='astronaut'?fabric:skin,.4,.12,0,-.2,0);const hand=sphere(elbow,skin,0,-.49,0,.12,.17,.1);sphere(elbow,skin,sign*.11,-.45,.01,.055,.09,.055);if(type==='astronaut')hand.material=white;const leg=new THREE.Group();leg.position.set(sign*.23,1.3,0);body.add(leg);capsule(leg,pants,.47,.18,0,-.24,0);const knee=new THREE.Group();knee.position.y=-.54;leg.add(knee);capsule(knee,pants,.43,.145,0,-.23,0);box(knee,white,0,-.51,.14,.36,.2,.63);box(knee,trim,0,-.6,.14,.37,.045,.64);if(type==='sport')box(leg,white,sign*.16,-.24,.04,.035,.5,.1);limbs[key]={arm,elbow,leg,knee}}
 const nameAnchor=new THREE.Object3D();nameAnchor.position.set(0,3.7,0);root.add(nameAnchor);return {root,body,hip,head,face,faceAnchor,nameAnchor,limbs,type,index,color,pose:{},phase:index*.37};}
 function choreography(style,t,energy,index){const b=t*Math.PI*2,p=Math.sin(b),q=Math.cos(b),slow=Math.sin(b*.5),s={x:0,y:.06+.07*(1+Math.sin(b*2)),z:0,rx:0,ry:Math.sin(b*.5)*.08,rz:p*.07,head:p*.07,Lax:-.28+p*.35,Rax:-.28-p*.35,Laz:.22,Raz:-.22,Lel:-.7,Rel:-.7,Llx:p*.2,Rlx:-p*.2,Lk:.13+Math.max(0,-p)*.25,Rk:.13+Math.max(0,p)*.25};
 if(style==='groove'){s.x=p*.16;s.rx=q*.07;s.Laz=.4+slow*.25;s.Raz=-.4+slow*.25;s.Lel=-1.1+q*.3;s.Rel=-1.1-q*.3;s.Llx=p*.32;s.Rlx=-p*.32}
 if(style==='shuffle'){s.x=p*.23;s.z=q*.12;s.y=.09+Math.abs(p)*.12;s.ry=q*.18;s.Llx=p*.65;s.Rlx=-p*.65;s.Lk=.2+Math.max(0,-q)*.9;s.Rk=.2+Math.max(0,q)*.9;s.Lax=-p*.6;s.Rax=p*.6}
 if(style==='disco'){const side=Math.sin(b*.25)>0?1:-1;s.x=p*.13;s.ry=slow*.2;s.Laz=side===1?2.4+q*.18:.45;s.Raz=side===-1?-2.4-q*.18:-.45;s.Lel=side===1?-.2:-1.2;s.Rel=side===-1?-.2:-1.2;s.Lax=-.2;s.Rax=-.2;s.rz=-side*.09}
 if(style==='wave'){s.x=slow*.16;s.rx=Math.sin(b*.5)*.16;s.ry=Math.sin(b*.25)*.22;s.Laz=1.3+Math.sin(b*.5)*.25;s.Raz=-1.3+Math.sin(b*.5+1)*.25;s.Lax=Math.sin(b*.5)*.35;s.Rax=Math.sin(b*.5+1)*.35;s.Lel=-.65+Math.sin(b*.5-1)*.6;s.Rel=-.65+Math.sin(b*.5-2)*.6;s.head=Math.sin(b*.5-1)*.16}
 if(style==='salsa'){s.x=Math.sin(b*.5)*.32;s.ry=p*.27;s.z=q*.13;s.Llx=p*.4;s.Rlx=-p*.4;s.Laz=.6+q*.35;s.Raz=-.6+q*.35;s.Lel=-1.3;s.Rel=-1.3;s.rz=p*.1}
 if(style==='robot'){const stop=Math.tanh(Math.sin(b)*5);s.x=stop*.1;s.ry=Math.tanh(Math.sin(b*.5)*4)*.28;s.Lax=-.75+stop*.5;s.Rax=-.75-stop*.5;s.Laz=.55;s.Raz=-.55;s.Lel=-1.55+Math.tanh(Math.sin(b+1)*5)*.5;s.Rel=-1.55-Math.tanh(Math.sin(b+1)*5)*.5;s.head=-stop*.13;s.y=.09;s.Llx=stop*.12;s.Rlx=-stop*.12}
 for(const k of Object.keys(s))if(!['y','Lel','Rel','Lk','Rk'].includes(k))s[k]*=energy;return s}
 function animateCharacter(c,beat,style,energy,dt,action,age,running=true){const s=choreography(style,beat+c.phase,energy,c.index);if(action&&age>=0&&age<2.8){const envelope=Math.sin(Math.min(1,age/2.8)*Math.PI);if(action==='spin')s.ry+=age/2.8*Math.PI*4;else if(action==='jump'){s.y+=Math.max(0,Math.sin(age*Math.PI*2))*envelope*.6;s.Laz+=envelope*1.7;s.Raz-=envelope*1.7}else if(action==='hello'){s.Raz=-2.4;s.Rel=-.6+Math.sin(age*12)*.5}}const a=Math.min(1,dt*(running?14:8));for(const k in s)c.pose[k]=(c.pose[k]??s[k])+((running?s[k]:({y:.08,Laz:.12,Raz:-.12,Lel:-.15,Rel:-.15,Lk:.03,Rk:.03}[k]||0))-(c.pose[k]??s[k]))*a;const v=c.pose;c.body.position.set(v.x,v.y,v.z);c.body.rotation.set(v.rx,v.ry,v.rz);c.head.rotation.z=v.head;for(const key of ['L','R']){const l=c.limbs[key];l.arm.rotation.set(v[key+'ax'],0,v[key+'az']);l.elbow.rotation.x=v[key+'el'];l.leg.rotation.x=v[key+'lx'];l.knee.rotation.x=v[key+'k']}}
 function disposeCharacter(c){c.root.traverse(o=>{if(o.isMesh){o.geometry.dispose();const mats=Array.isArray(o.material)?o.material:[o.material];for(const m of mats){m.map?.dispose();m.dispose()}}})}
 window.DanceModels={create:createCharacter,animate:animateCharacter,dispose:disposeCharacter,palettes};
})();
